var terrainGo = GameObject.Find("LowpolyTerrain");
var pts = new Vector3[] { new Vector3(-25f, 0f, -15f), new Vector3(20f, 0f, -20f) };
foreach (var p in pts)
{
    var hits = Physics.RaycastAll(new Ray(new Vector3(p.x, 200f, p.z), Vector3.down), 400f);
    float bestAny = float.MaxValue; string anyName = "-"; float anyY = float.NaN;
    float bestTerr = float.MaxValue; float terrY = float.NaN;
    for (int i = 0; i < hits.Length; i++)
    {
        if (hits[i].distance < bestAny) { bestAny = hits[i].distance; anyY = hits[i].point.y; anyName = hits[i].collider.gameObject.name; }
        var t = hits[i].collider.transform;
        if ((t == terrainGo.transform || t.IsChildOf(terrainGo.transform)) && hits[i].distance < bestTerr) { bestTerr = hits[i].distance; terrY = hits[i].point.y; }
    }
    Debug.Log("[T] xz=(" + p.x + "," + p.z + ") naiveFirst=" + anyName + " y=" + anyY.ToString("F3") + " | terrainOnly y=" + terrY.ToString("F3"));
}
